package Day3;

public class ForLoopDemo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
      for(int i=1;i<=5;i=i+1)
      {
    	  System.out.println("Dev Kumar Chaubey "+i);
      }
	}

}

